INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist NDP nur für die Routererkennung da?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Nachbarn und SLAAC"}, {"text": "Ja", "correct": false, "because": "Funktion ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat NDP in einem Netzwerk?', 3, '[{"text": "Geräteerkennung", "correct": true, "because": "Findet Nachbarn"}, {"text": "Paketverschlüsselung", "correct": false, "because": "Nicht NDP-Aufgabe"}, {"text": "Bandbreitensteuerung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse unterstützt NDP?', 5, '[{"text": "Neighbor Solicitation", "correct": true, "because": "Fragt nach MAC"}, {"text": "SLAAC", "correct": true, "because": "Automatische Adresszuweisung"}, {"text": "Datenkompression", "correct": false, "because": "Nicht NDP"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NDP ersetzt ARP. b) Es nutzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMPv6, nicht TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von NDP?', 4, '[{"text": "Neighbor Advertisement", "correct": false, "because": "Antwort auf Solicitation"}, {"text": "Router Solicitation", "correct": false, "because": "Findet Router"}, {"text": "Portnummern", "correct": true, "because": "Schicht 4, nicht NDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SLAAC eine Serverantwort braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Autonom via Router"}, {"text": "Ja", "correct": false, "because": "Kein DHCP nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht sende ich, um Router zu finden?', 3, '[{"text": "Router Solicitation", "correct": true, "because": "Fragt Router ab"}, {"text": "Echo Request", "correct": false, "because": "Nur Erreichbarkeit"}, {"text": "Neighbor Advertisement", "correct": false, "because": "Antwort, kein Request"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet NDP?', 5, '[{"text": "Adressauflösung", "correct": true, "because": "MAC zu IP"}, {"text": "Autokonfiguration", "correct": true, "because": "Via SLAAC"}, {"text": "Paketweiterleitung", "correct": false, "because": "Router-Aufgabe"}, {"text": "Fehlerkorrektur", "correct": false, "because": "Andere Protokolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) NDP nutzt Multicast. b) Es ersetzt DHCP komplett. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SLAAC ergänzt DHCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für NDP?', 4, '[{"text": "Router Advertisement", "correct": false, "because": "Für SLAAC nötig"}, {"text": "Neighbor Solicitation", "correct": false, "because": "Kernfunktion"}, {"text": "HTTP-Anfragen", "correct": true, "because": "Andere Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist NDP optional bei IPv6?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprotokoll für IPv6"}, {"text": "Ja", "correct": false, "because": "Pflichtfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pakete helfen mir bei der Adresszuweisung?', 4, '[{"text": "Router Advertisement", "correct": true, "because": "Enthält Präfix für SLAAC"}, {"text": "Echo Reply", "correct": false, "because": "Nur Diagnose"}, {"text": "Neighbor Solicitation", "correct": false, "because": "Nur Erkennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass NDP nur für lokale Netze ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Link-lokal beschränkt"}, {"text": "Nein", "correct": false, "because": "Nur lokal relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der NDP-Nutzung?', 3, '[{"text": "Router Advertisement", "correct": true, "because": "Ermöglicht SLAAC"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "Latenzmessung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLAAC nutzt Router Advertisement. b) NDP blockiert Pakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Firewall-Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet NDP?', 5, '[{"text": "Automatische Adresszuweisung", "correct": true, "because": "Via SLAAC"}, {"text": "Nachbarschaftserkennung", "correct": true, "because": "Findet Geräte"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht NDP"}, {"text": "Routing-Optimierung", "correct": false, "because": "Router-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei NDP unwichtig?', 3, '[{"text": "Neighbor Solicitation", "correct": false, "because": "Kern der Erkennung"}, {"text": "Router Advertisement", "correct": false, "because": "Für SLAAC nötig"}, {"text": "DNS-Abfragen", "correct": true, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt NDP Unicast für alles?', 3, '[{"text": "Nein", "correct": true, "because": "Multicast für Solicitation"}, {"text": "Ja", "correct": false, "because": "Multicast ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SLAAC eine MAC-Adresse braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Für Interface-ID"}, {"text": "Nein", "correct": false, "because": "MAC ist Basis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht nutze ich, um Geräte im Netz zu finden?', 4, '[{"text": "Neighbor Solicitation", "correct": true, "because": "Fragt nach Nachbarn"}, {"text": "Router Advertisement", "correct": false, "because": "Router-Info"}, {"text": "Echo Request", "correct": false, "because": "Nur Erreichbarkeit"}]');
